function PublicNav(){return <nav className="nav2"><Link to="/" style={{display:'flex',alignItems:'center',gap:10}}><img src="/logo.jpg" alt=""/><b>BMYF Database</b></Link><span className="sp"/>{/* <Link className="lk" to="/#about">About</Link><Link className="lk" to="/#groups">Groups</Link><Link className="lk" to="/contact">Contact</Link> */}<Link className="btn y s" to="/#signin">Sign in</Link></nav>}
/* CONTACT PAGE (hidden for now; re-enable with its route above and a nav link)
function Contact(){const [f,s]=useState({name:'',email:'',phone:'',subject:'',message:'',website:''}),[sent,setSent]=useState(false),[busy,setBusy]=useState(false),u=k=>e=>s({...f,[k]:e.target.value})
return <div><PublicNav/><header className="hero" style={{padding:'120px clamp(18px,5vw,64px) 60px'}}><div style={{maxWidth:1100,margin:'auto'}}><h1 style={{fontSize:'clamp(32px,5vw,52px)',margin:0}}>Contact <b>us</b></h1><p style={{opacity:.9,fontSize:18,maxWidth:560}}>Come and worship with us, or send us a message about anything. We'll get back to you.</p></div></header>
<section className="sec"><div className="two" style={{alignItems:'start'}}><div style={{display:'grid',gap:16}}>
<a className="pc" href={'tel:+233'+PHONE.slice(1)}><Ic n="phone"/><h3>Call us</h3><p style={{fontSize:20,color:'#fff'}}>{PHONE}</p></a>
<a className="pc" href={'mailto:'+MAIL}><Ic n="mail"/><h3>Email us</h3><p style={{fontSize:17,color:'#fff'}}>{MAIL}</p></a>
<a className="pc" href={'https://www.google.com/maps/search/?api=1&query='+MQ} target="_blank" rel="noreferrer"><Ic n="pin"/><h3>Visit us</h3><p style={{fontSize:17,color:'#fff'}}>{ADDR}</p><span>Get directions →</span></a></div>
<div className="card">{sent?<div style={{textAlign:'center',padding:'30px 10px'}}><h3 style={{fontSize:22}}>Thank you!</h3><p>Your message has been sent. We'll get back to you soon.</p><button className="btn y" onClick={()=>{setSent(false);s({name:'',email:'',phone:'',subject:'',message:'',website:''})}}>Send another message</button></div>:
<form onSubmit={async e=>{e.preventDefault();setBusy(true);try{await api('/contact',{method:'POST',body:f});setSent(true)}catch(x){toast(x.message)}setBusy(false)}}><h3>Send us a message</h3><Field l="Full name *" name="name" required minLength={2} value={f.name} onChange={u('name')}/><Field l="Email *" name="email" type="email" required value={f.email} onChange={u('email')}/><Field l="Phone (optional)" name="phone" value={f.phone} onChange={u('phone')}/><Field l="Subject *" name="subject" required minLength={2} value={f.subject} onChange={u('subject')}/>
<label>Message *</label><textarea name="message" rows={5} required minLength={10} maxLength={2000} value={f.message} onChange={u('message')}/>
<input name="website" tabIndex={-1} autoComplete="off" aria-hidden="true" style={{position:'absolute',left:'-9999px',width:1}} value={f.website} onChange={u('website')}/><button className="btn y" style={{marginTop:16,width:'100%'}} disabled={busy}>{busy?'Sending…':'Send message'}</button></form>}</div></div>
<h2 style={{marginTop:50}}>Find us</h2><p className="lead">{ADDR}</p><div className="mapbox"><iframe title="Map to Beulah Methodist Church" src={'https://www.google.com/maps?q='+MQ+'&output=embed'} loading="lazy" referrerPolicy="no-referrer-when-downgrade" allowFullScreen/></div>
<a className="btn" href={'https://www.google.com/maps/search/?api=1&query='+MQ} target="_blank" rel="noreferrer">Open in Google Maps</a></section>
<footer className="foot">© {new Date().getFullYear()} Beulah Methodist Youth Fellowship · We Work. We Witness. We Worship.<br/>~ By Kingsley Quarshie.</footer><Toasts/></div>}
*/
const DAYMS=864e5
const clock=t=>new Date(t).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}),dayLabel=t=>{const d=new Date(t),n=new Date();return d.toDateString()===n.toDateString()?'Today':new Date(n-DAYMS).toDateString()===d.toDateString()?'Yesterday':d.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'})}
function Thread({who,name,sub,onBack,after}){const r=useLoad('/chat/messages?with='+who,5000),[text,setText]=useState(''),[busy,setBusy]=useState(false),box=useRef(null),n=r.data?.length||0
useEffect(()=>{if(box.current)box.current.scrollTop=box.current.scrollHeight},[n])
useEffect(()=>{if(r.data)after()},[!!r.data])
const send=async()=>{const t=text.trim();if(!t||busy)return;setBusy(true);try{await api('/chat/messages',{method:'POST',body:{to:who,text:t}});setText('');r.reload();after()}catch(e){toast(e.message)}setBusy(false)}
const del=async id=>{if(!window.confirm('Delete this message?'))return;try{await api('/chat/messages/'+id,{method:'DELETE'});r.reload();after()}catch(e){toast(e.message)}}
let last=''
return <div className="cthread"><div className="chead"><button type="button" className="btn g s cback" onClick={onBack}>Back</button><div className="av">{who==='all'?<Ic n="users"/>:ini(name)}</div><div><b>{name}</b><small>{sub}</small></div></div>
<div className="cmsgs" ref={box}>{!r.data?<div className="empty">{r.err||'Loading…'}</div>:r.data.length?r.data.map(m=>{const dl=dayLabel(m.at),head=dl!==last;last=dl;return <div key={m._id}>{head&&<div className="cday">{dl}</div>}<div className={'cmsg'+(m.mine?' mine':'')}>{who==='all'&&!m.mine&&<small className="cwho">{m.from.fullName}{m.from.role&&' · '+ROLE[m.from.role]}</small>}<div className="cbub">{m.deleted?<i>Message deleted</i>:m.text}</div><small className="ctime">{clock(m.at)}{m.mine&&!m.deleted&&<> · <button type="button" className="lnk" onClick={()=>del(m._id)}>Delete</button></>}</small></div></div>}):<div className="empty">No messages yet. Say hello.</div>}</div>
<form className="cform" onSubmit={e=>{e.preventDefault();send()}}><textarea rows={1} aria-label="Type a message" placeholder="Type a message" maxLength={2000} value={text} onChange={e=>setText(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}}}/><button className="btn y" disabled={busy||!text.trim()}>Send</button></form></div>}
function Chat(){const pl=useLoad('/chat/people',15000),[cur,setCur]=useState(null),[q,setQ]=useState(''),ps=pl.data?.people||[],people=ps.filter(p=>p.fullName.toLowerCase().includes(q.toLowerCase())),pp=ps.find(x=>x._id===cur),
sel=cur==='all'?{name:'All staff',sub:'Every staff member can read and reply here'}:pp&&{name:pp.fullName,sub:ROLE[pp.role]+(pp.group?' · '+pp.group:'')},after=()=>{pl.reload();refreshBadges()}
return <div className={'chat card'+(cur?' open':'')}><div className="clist"><input placeholder="Search staff" aria-label="Search staff" value={q} onChange={e=>setQ(e.target.value)}/>
<button type="button" className={'crow'+(cur==='all'?' on':'')} onClick={()=>setCur('all')}><div className="av"><Ic n="users"/></div><div className="n"><b>All staff</b><small>{pl.data?.channel.last?(pl.data.channel.last.mine?'You':pl.data.channel.last.by||'Someone')+': '+pl.data.channel.last.text:'Message everyone'}</small></div>{pl.data?.channel.unread>0&&<span className="bdg">{pl.data.channel.unread}</span>}</button>
{pl.data?(people.length?people.map(p=><button type="button" key={p._id} className={'crow'+(cur===p._id?' on':'')} onClick={()=>setCur(p._id)}><div className="av">{ini(p.fullName)}</div><div className="n"><b>{p.fullName}</b><small>{ROLE[p.role]}{p.group?' · '+p.group:''}</small>{p.last&&<small>{p.last.mine?'You: ':''}{p.last.text}</small>}</div>{p.unread>0&&<span className="bdg">{p.unread}</span>}</button>):<div className="empty">No staff found.</div>):<div className="empty">{pl.err||'Loading…'}</div>}</div>
{cur&&sel?<Thread key={cur} who={cur} name={sel.name} sub={sel.sub} onBack={()=>setCur(null)} after={after}/>:<div className="cthread cempty"><div className="empty">Choose a person or All staff to start chatting.</div></div>}</div>}
