const Private=({children,admin})=>{const {user}=useAuth();if(user===undefined)return <div className="empty">Loading…</div>;if(!user)return <Navigate to="/"/>;if(admin&&!ADM.includes(user.role))return <Navigate to="/dashboard"/>;return children}
export default function App(){const [user,setUser]=useState();useEffect(()=>{api('/auth/me').then(setUser).catch(()=>setUser(null))},[])
const P=(C,admin)=><Private admin={admin}><C/></Private>
return <Ctx.Provider value={{user,setUser}}><BrowserRouter><Routes><Route path="/" element={<Landing/>}/><Route path="/login" element={<Navigate to="/#signin"/>}/><Route path="/login/:portal" element={<Login/>}/><Route path="/admin/login" element={<Login p="admin"/>}/><Route path={SA} element={<Login p="super-admin"/>}/>{/* <Route path="/contact" element={<Contact/>}/> */}<Route path={SU} element={<SuperSignup/>}/><Route path="/messages" element={P(Messages)}/><Route path="/forgot-password" element={<Forgot/>}/><Route path="/reset-password" element={<Reset/>}/><Route path="/dashboard" element={P(Dashboard)}/><Route path="/members" element={P(Members)}/><Route path="/members/new" element={<Private><Members key="n" mode="new"/></Private>}/><Route path="/visitors" element={<Private><Members key="v" mode="visitors"/></Private>}/><Route path="/profile" element={P(MyProfile)}/><Route path="/settings" element={P(Settings,1)}/><Route path="/attendance" element={P(Attendance)}/><Route path="/attendance/new" element={<Private><Attendance key="n" mode="new"/></Private>}/><Route path="/attendance/:id" element={P(TakeAttendance)}/><Route path="/followups" element={P(FollowUps)}/><Route path="/birthdays" element={P(Birthdays)}/><Route path="/reports" element={P(Reports)}/><Route path="/staff" element={P(Staff,1)}/><Route path="/audit" element={P(Audit,1)}/><Route path="*" element={<Navigate to="/"/>}/></Routes></BrowserRouter><Toasts/></Ctx.Provider>}
